/** Uma linha por temporada: pôster pequeno (sem ele, o número), nome, ano e episódios. */
export function Temporadas({ temporadas }: { temporadas: Temporada[] }) {
  return (
    <ul className="divide-border/60 flex max-w-3xl flex-col divide-y">
      {temporadas.map((temporada) => {
        const poster = urlImagem(temporada.posterPath, "w92");
        const detalhes = [temporada.ano, contar(temporada.episodios, "episódio", "episódios")]
          .filter(Boolean)
          .join(" · ");
        return (
          <li key={temporada.numero} className="flex items-center gap-4 py-3">
            <div className="bg-muted relative aspect-[2/3] w-12 shrink-0 overflow-hidden rounded-md">
              {poster ? (
                <Image src={poster} alt="" fill sizes="48px" className="object-cover" />
              ) : (
                <span
                  aria-hidden="true"
                  className="text-muted-foreground flex h-full items-center justify-center text-sm font-semibold"
                >
                  {temporada.numero}
                </span>
              )}
            </div>
            <div>
              <p className="font-medium">{temporada.nome}</p>
              <p className="text-muted-foreground text-sm">{detalhes}</p>
            </div>
          </li>
        );
      })}
    </ul>
  );
}
import { formatarDuracao, formatarNota } from "@/features/filme/formatar";
import type { ClassificacaoBR, SerieDetalhes } from "@/lib/tmdb/tipos";

/** "1 temporada", "2 temporadas". */
export function contar(quantidade: number, singular: string, plural: string): string {
  return `${quantidade} ${quantidade === 1 ? singular : plural}`;
}

/** "Livre" ou "12 anos"; `null` sem classificação no Brasil. */
export function rotuloClassificacao(classificacao: ClassificacaoBR | null): string | null {
  if (!classificacao) return null;
  return classificacao === "L" ? "Livre" : `${classificacao} anos`;
}

/** Linha de dados do cabeçalho: ano · temporadas · episódio · classificação · nota. */
export function dadosDaSerie(serie: SerieDetalhes): (string | null)[] {
  const episodio = formatarDuracao(serie.duracaoEpisodioMin);
  return [
    serie.ano ? String(serie.ano) : null,
    serie.temporadas.length > 0 ? contar(serie.temporadas.length, "temporada", "temporadas") : null,
    episodio ? `Episódios de ${episodio}` : null,
    rotuloClassificacao(serie.classificacao),
    formatarNota(serie.nota, serie.votos),
  ];
}
/** "2h 19min", "2h", "45min"; `null` para duração ausente. */
export function formatarDuracao(minutos: number | null): string | null {
  if (!minutos) return null;
  const horas = Math.floor(minutos / 60);
  const resto = minutos % 60;
  if (!horas) return `${resto}min`;
  return resto ? `${horas}h ${resto}min` : `${horas}h`;
}

const numeroPtBr = new Intl.NumberFormat("pt-BR");

export function formatarVotos(votos: number): string {
  return numeroPtBr.format(votos);
}

/** "Clube da Luta (1999)"; sem ano, só o título. */
export function tituloComAno({ titulo, ano }: { titulo: string; ano: number | null }): string {
  return ano ? `${titulo} (${ano})` : titulo;
}

/** "★ 8.4 (30.000 votos)". */
export function formatarNota(nota: number, votos: number): string {
  return `★ ${nota.toFixed(1)} (${formatarVotos(votos)} votos)`;
}
import { cache } from "react";

/** Só inteiros positivos de até 10 dígitos são IDs válidos do TMDB. */
export function lerId(valor: string): number | null {
  if (!/^\d{1,10}$/.test(valor)) return null;
  const id = Number(valor);
  return id > 0 ? id : null;
}

/**
 * Busca da página `/{tipo}/[id]`: ID inválido vira `null` sem ir ao TMDB. Uma busca por
 * renderização, compartilhada entre a página e o título da aba (`generateMetadata`).
 */
export function buscaPorId<T>(obter: (id: number) => Promise<T | null>) {
  return cache(async (valor: string): Promise<T | null> => {
    const id = lerId(valor);
    return id ? obter(id) : null;
  });
}
