describe("descobrirSeries", () => {
  it("traduz os filtros para os parâmetros do /discover/tv, sem region", async () => {
    const { api, fetchFalso } = montar(paginaTmdb([]));

    await api.descobrirSeries({
      todosGeneros: [35, 18],
      semGeneros: [16],
