    });

    const { url, revalidate } = chamada(fetchFalso);
    expect(url.pathname).toBe("/3/discover/tv");
    expect(Object.fromEntries(url.searchParams)).toEqual({
      with_genres: "35,18",
      without_genres: "16",
      with_watch_providers: "8|337",
      watch_region: "BR",
      with_watch_monetization_types: "flatrate",
      "with_runtime.gte": "20",
      "with_runtime.lte": "30",
